content.content:
// Dispatch generation front, modeled on code-search's federation
// (routes/code-search.ts): resolve the selected repos and read each repo's
// checkpoints from its home cell via entire-api, replacing the former
// the legacy store checkRepoAccess gate + the legacy store checkpoint read at the front of
// POST /dispatches/generate. Access is enforced at each cell by entire-api via
// the identity token — there is no BFF-side access gate and no the legacy store
// fallback. Returns the built DispatchDetail plus the region-scoped repo ULIDs
// (canonical placement ids) that key the v2 runner persistence.
//
// Two auth modes:
//   - Browser session: exchange the login JWT, resolve repos through the
//     federated core index (cross-jurisdiction), and mint a jurisdiction token
//     per cell.
//   - Bearer/CLI (entire dispatch): an api-access bearer can't authenticate the
//     federated core index, so resolve + read against the caller's HOME cell via
//     proxyEntireApiHome. In-region only; a selected repo outside the home
//     region atomic-fails (deferred with the residency work).

import type { Context } from "hono"
import { getCookie } from "hono/cookie"

import type { Env, Variables } from "../env"
import { bearerTokenFromAuthorization } from "./authorization-header"
import { normalizeScopeValues, type CreateDispatchRequest, type DispatchDetail } from "./dispatch"
import {
  buildDispatchDetailViaFanout,
  resolveDispatchRepos,
  type ResolvedDispatchRepo,
} from "./dispatch-fanout"
import { buildEntireApiDeps, isEntireApiHomeConfigured } from "./entire-api/deps"
import {
  createEntireApiCheckpointReader,
  createHomeEntireApiCheckpointReader,
  listHomeRepos,
} from "./entire-api/dispatch-checkpoints-read"
import { coreClientConfigFromAuth, getCoreAuthConfig } from "./entire-core/config"
import { getValidLoginJwt } from "./entire-core/core-login"
import { resolveCoreBaseUrlForLoginJwt } from "./entire-core/trusted-issuer"
import {
  listReposIndex,
  normalizeRepoSlug,
  type ReposIndexRow,
} from "./repos-federation/list-repos-index"

export type ResolveDispatchOutcome =
  | {
      kind: "ok"
      record: DispatchDetail | null
      // Canonical `owner/repo` full_names from resolution, positionally parallel
      // to scopeRepoUlids. Persisted as the run's identity (NOT the raw caller
      // slugs) so `repos`, `repo_ulids`, and `covered_repos` all agree — the
      // covered_repo_ulids projection and setup dedup depend on that.
      scopeRepos: string[]
      scopeRepoUlids: string[]
    }
  | { kind: "error"; response: Response }

function errorResponse(status: 401 | 404 | 502 | 503, message: string): Response {
  return Response.json({ error: message }, { status })
}

// Walk every page of the caller's federated repos index and return all rows.
// Used when a selection includes a bare ULID (core's full_name filter can't
// surface it) and by the view-auth ULID set — both need the complete set, since
// a repo on a later page would otherwise be missed.
// Hard ceiling on index pages walked — a backstop against a core that echoes a
// non-empty token forever. At core's page sizes this is far more repos than any
// real caller has; hitting it means something is wrong upstream, so stop.
const MAX_INDEX_PAGES = 100

async function listAllIndexRepos(
  coreBaseUrl: string,
  loginJwt: string,
  fetchTimeoutMs: number | undefined,
): Promise<ReposIndexRow[]> {
  const rows: ReposIndexRow[] = []
  const seenTokens = new Set<string>()
  let pageToken: string | undefined
  for (let i = 0; i < MAX_INDEX_PAGES; i++) {
    const page = await listReposIndex({ coreBaseUrl, loginJwt, pageToken, fetchTimeoutMs })
    rows.push(...page.repos)
    const next = page.nextPageToken || undefined
    // Stop on a terminal page OR a token that doesn't advance (a stale/echoed
    // token would otherwise loop forever).
    if (!next || seenTokens.has(next)) break
    seenTokens.add(next)
    pageToken = next
  }
  return rows
