package httpapi
import (
	"context"
	"encoding/json"
	"time"
	"github.com/entirehq/entire-api/internal/dispatch"
	"github.com/entirehq/entire-api/internal/store"
)
// dispatchStore is the narrow store interface the handlers consume;
// *store.UserStore satisfies it, tests inject a fake.
type dispatchStore interface {
	UpsertDispatchSetupByConfig(ctx context.Context, accountID, configHash string, configJSON json.RawMessage) (store.DispatchSetup, error)
	GetDispatchSetup(ctx context.Context, accountID, setupID string) (store.DispatchSetup, bool, error)
	ListDispatchSetups(ctx context.Context, accountID string, limit int, cursor *store.DispatchCursor) ([]store.DispatchSetup, *store.DispatchCursor, error)
	UpdateDispatchSetup(ctx context.Context, accountID, setupID string, name **string, pinned *bool) (store.DispatchSetup, bool, error)
	SoftDeleteDispatchSetup(ctx context.Context, accountID, setupID string) (bool, error)
	InsertDispatchRun(ctx context.Context, accountID, setupID, model string, requestJSON json.RawMessage) (store.DispatchRun, bool, error)
	CompleteDispatchRun(ctx context.Context, accountID, runID, markdown string) (store.DispatchRun, bool, error)
	FailDispatchRun(ctx context.Context, accountID, runID, errMsg string) (store.DispatchRun, bool, error)
	GetDispatchRun(ctx context.Context, accountID, runID string) (store.DispatchRun, bool, error)
	ListDispatchRunsForSetup(ctx context.Context, accountID, setupID string, limit int, cursor *store.DispatchCursor) ([]store.DispatchRun, *store.DispatchCursor, error)
	ListRecentDispatchRunsForSetups(ctx context.Context, accountID string, setupIDs []string, perSetup int) (map[string][]store.DispatchRun, error)
	SoftDeleteDispatchRun(ctx context.Context, accountID, runID string) (bool, error)
	MostRecentDispatchRunAt(ctx context.Context, accountID string) (*time.Time, error)
}
var _ dispatchStore = (*store.UserStore)(nil)
// A run stuck in "running" this long is reported as failed rather than
// generating forever. Must exceed the real ceiling
// (dispatchGenerationTimeout + dispatchPersistTimeout = 90s); kept close to
// it rather than a wide margin like the old 5m, so a run that actually died
// at 80s doesn't keep reading "generating" for minutes afterward.
// Presentational only — the row itself stays "running" in Postgres until a
// sweeper or runner-backed executor exists.
const dispatchStaleGeneratingThreshold = 2 * time.Minute
// The scaffold's dispatch.* types keep snake_case tags as the prompt/persistence
// shape, so the response gets its own camelCase DTOs. Passing the domain types
// through would put the prompt contract on the wire.
type DispatchWindowWire struct {
	NormalizedSince          string  `json:"normalizedSince"`
	NormalizedUntil          string  `json:"normalizedUntil"`
	FirstCheckpointCreatedAt *string `json:"firstCheckpointCreatedAt"`
	LastCheckpointCreatedAt  *string `json:"lastCheckpointCreatedAt"`
}
type DispatchTotalsWire struct {
	Checkpoints         int `json:"checkpoints"`
	UsedCheckpointCount int `json:"usedCheckpointCount"`
	Branches            int `json:"branches"`
	FilesTouched        int `json:"filesTouched"`
}
type DispatchBulletWire struct {
	CheckpointID string   `json:"checkpointId"`
	Text         string   `json:"text"`
	Source       string   `json:"source"`
	Branch       string   `json:"branch"`
	CreatedAt    string   `json:"createdAt"`
	Labels       []string `json:"labels"`
}
type DispatchSectionWire struct {
	Label   string               `json:"label"`
	Bullets []DispatchBulletWire `json:"bullets"`
}
type DispatchRepoGroupWire struct {
	FullName string                `json:"fullName"`
	Sections []DispatchSectionWire `json:"sections"`
}
func dispatchWindowWire(w dispatch.Window) DispatchWindowWire {
	return DispatchWindowWire{
		NormalizedSince:          w.NormalizedSince,
		NormalizedUntil:          w.NormalizedUntil,
		FirstCheckpointCreatedAt: w.FirstCheckpointCreatedAt,
		LastCheckpointCreatedAt:  w.LastCheckpointCreatedAt,
	}
}
func dispatchTotalsWire(t dispatch.Totals) DispatchTotalsWire {
	return DispatchTotalsWire{
		Checkpoints:         t.Checkpoints,
		UsedCheckpointCount: t.UsedCheckpointCount,
		Branches:            t.Branches,
		FilesTouched:        t.FilesTouched,
	}
}
// Empty slices rather than nil: a null reads as "unknown", not "none".
func dispatchReposWire(groups []dispatch.RepoGroup) []DispatchRepoGroupWire {
	out := make([]DispatchRepoGroupWire, 0, len(groups))
	for _, g := range groups {
		sections := make([]DispatchSectionWire, 0, len(g.Sections))
		for _, sec := range g.Sections {
			bullets := make([]DispatchBulletWire, 0, len(sec.Bullets))
			for _, b := range sec.Bullets {
				bullets = append(bullets, DispatchBulletWire{
					CheckpointID: b.CheckpointID,
					Text:         b.Text,
					Source:       string(b.Source),
					Branch:       b.Branch,
					CreatedAt:    b.CreatedAt,
					Labels:       b.Labels,
				})
			}
			sections = append(sections, DispatchSectionWire{Label: sec.Label, Bullets: bullets})
		}
		out = append(out, DispatchRepoGroupWire{FullName: g.FullName, Sections: sections})
	}
	return out
}
