package dispatch

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
)

func newTestCloudClient(t *testing.T, baseURL, token string) *CloudClient {
	t.Helper()
	transport := &http.Transport{DisableKeepAlives: true}
	t.Cleanup(transport.CloseIdleConnections)
	return NewCloudClient(CloudConfig{
		BaseURL: baseURL,
		Token:   token,
		HTTP: &http.Client{
			Transport: transport,
			Timeout:   defaultCloudHTTPTimeout,
		},
	})
}

// completeDispatchJSON is a terminal cell response in DispatchDetailWire shape.
func completeDispatchJSON(id, markdown string) string {
	return fmt.Sprintf(`{"id":%q,"setupId":"setup-1","status":"complete","title":null,"coveredRepos":["entireio/cli"],"coveredRepoUlids":["01X"],"branches":[],"voice":null,"window":{"normalizedSince":"2026-04-09T00:00:00Z","normalizedUntil":"2026-04-16T00:00:00Z","firstCheckpointCreatedAt":null,"lastCheckpointCreatedAt":null},"totals":{"checkpoints":1,"usedCheckpointCount":1,"branches":1,"filesTouched":2},"repos":[],"generatedMarkdown":%q,"isPersisted":true,"errorMessage":null,"createdAt":"2026-04-16T00:00:00Z","updatedAt":"2026-04-16T00:00:01Z","completedAt":"2026-04-16T00:00:01Z"}`, id, markdown)
}

func generatingDispatchJSON(id string) string {
	return fmt.Sprintf(`{"id":%q,"setupId":"setup-1","status":"generating","title":null,"coveredRepos":["entireio/cli"],"branches":[],"voice":null,"window":{"normalizedSince":"2026-04-09T00:00:00Z","normalizedUntil":"2026-04-16T00:00:00Z","firstCheckpointCreatedAt":null,"lastCheckpointCreatedAt":null},"totals":{"checkpoints":1,"usedCheckpointCount":1,"branches":1,"filesTouched":2},"repos":[],"generatedMarkdown":"","isPersisted":true,"errorMessage":null,"createdAt":"2026-04-16T00:00:00Z","updatedAt":"2026-04-16T00:00:00Z","completedAt":null}`, id)
}

// shortenDispatchPoll shrinks the package-level poll knobs for the duration of
// a test. Tests using it mutate shared state and must NOT call t.Parallel().
func shortenDispatchPoll(t *testing.T, interval, timeout time.Duration) {
	t.Helper()
	oldInterval, oldTimeout := dispatchPollInterval, dispatchPollTimeout
	dispatchPollInterval, dispatchPollTimeout = interval, timeout
	t.Cleanup(func() { dispatchPollInterval, dispatchPollTimeout = oldInterval, oldTimeout })
}

func TestCloudClient_CreateDispatch_Happy(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != testDispatchEndpoint {
			http.NotFound(w, r)
			return
		}
		if r.Header.Get("Authorization") == "" {
			w.WriteHeader(http.StatusUnauthorized)
			return
		}
		if r.URL.Query().Has(jurisdictionQueryParam) {
			t.Errorf("home-jurisdiction request must not send a %s selector, got %q", jurisdictionQueryParam, r.URL.RawQuery)
		}

		var body map[string]any
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
			return
		}
		repos, ok := body["repos"].([]any)
		if !ok || len(repos) != 1 || repos[0] != testRepoFullName {
			t.Errorf("bad repos payload: %v", body["repos"])
		}
		for _, forbidden := range []string{"repo", "wait", "generate", "branches", "orgs", "jurisdiction"} {
			if _, ok := body[forbidden]; ok {
				t.Errorf("did not expect %q in request body: %v", forbidden, body)
			}
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusAccepted)
		_, _ = w.Write([]byte(generatingDispatchJSON("run-1"))) //nolint:errcheck // test fixture response
	}))
	defer srv.Close()

	client := newTestCloudClient(t, srv.URL, "t")
	got, err := client.CreateDispatch(ctx, CreateDispatchRequest{
		Repos: []string{testRepoFullName},
		Since: "2026-04-09T00:00:00Z",
		Until: "2026-04-16T00:00:00Z",
	}, "")
	if err != nil {
		t.Fatal(err)
	}
	if got.ID != "run-1" || got.Status != DispatchStatusGenerating {
		t.Fatalf("unexpected detail: %+v", got)
	}
}

func TestCloudClient_CreateDispatch_SendsJurisdictionSelectorAsQueryOnly(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if got := r.URL.Query().Get(jurisdictionQueryParam); got != "us" {
			t.Errorf("expected ?jurisdiction=us, got query %q", r.URL.RawQuery)
		}
		var body map[string]any
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
			t.Error(err)
			return
		}
		if _, ok := body["jurisdiction"]; ok {
			t.Errorf("jurisdiction is a gateway query selector and must not be in the body: %v", body)
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(completeDispatchJSON("run-1", "hi"))) //nolint:errcheck // test fixture response
	}))
	defer srv.Close()

	client := newTestCloudClient(t, srv.URL, "t")
	got, err := client.CreateDispatch(ctx, CreateDispatchRequest{
		Repos: []string{testRepoFullName},
		Since: "2026-04-09T00:00:00Z",
		Until: "2026-04-16T00:00:00Z",
	}, "us")
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedMarkdown != "hi" || got.Status != DispatchStatusComplete {
		t.Fatalf("unexpected detail: %+v", got)
	}
}

func TestCloudClient_GetDispatch_EscapesIDAndCarriesJurisdiction(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			t.Errorf("expected GET, got %s", r.Method)
		}
		if want := testDispatchEndpoint + "/run%2F..%2Fx"; r.URL.RawPath != want && r.URL.EscapedPath() != want {
			t.Errorf("expected escaped id in path, got %q", r.URL.EscapedPath())
		}
		if got := r.URL.Query().Get(jurisdictionQueryParam); got != "eu" {
			t.Errorf("poll must carry the same selector as the POST, got query %q", r.URL.RawQuery)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(completeDispatchJSON("run/../x", "hi"))) //nolint:errcheck // test fixture response
	}))
	defer srv.Close()

	client := newTestCloudClient(t, srv.URL, "t")
	got, err := client.GetDispatch(context.Background(), "run/../x", "eu")
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedMarkdown != "hi" {
		t.Fatalf("unexpected detail: %+v", got)
	}

	if _, err := client.GetDispatch(context.Background(), "  ", "eu"); err == nil {
		t.Fatal("expected error for blank id")
	}
}

func TestCloudClient_WaitForDispatch_PollsSameJurisdictionUntilComplete(t *testing.T) {
	shortenDispatchPoll(t, 5*time.Millisecond, 5*time.Second)

	var polls atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet || r.URL.Path != testDispatchEndpoint+"/run-7" {
			t.Errorf("unexpected poll %s %s", r.Method, r.URL.Path)
			http.NotFound(w, r)
			return
		}
		if got := r.URL.Query().Get(jurisdictionQueryParam); got != "au" {
			t.Errorf("poll must carry ?jurisdiction=au, got %q", r.URL.RawQuery)
		}
		w.Header().Set("Content-Type", "application/json")
		if polls.Add(1) < 3 {
			_, _ = w.Write([]byte(generatingDispatchJSON("run-7"))) //nolint:errcheck // test fixture response
			return
		}
		_, _ = w.Write([]byte(completeDispatchJSON("run-7", "done"))) //nolint:errcheck // test fixture response
	}))
	defer srv.Close()

	client := newTestCloudClient(t, srv.URL, "t")
	got, err := client.WaitForDispatch(context.Background(), &DispatchDetail{ID: "run-7", Status: DispatchStatusGenerating}, "au")
	if err != nil {
		t.Fatal(err)
	}
	if got.GeneratedMarkdown != "done" {
		t.Fatalf("unexpected final detail: %+v", got)
	}
	if polls.Load() != 3 {
		t.Fatalf("expected 3 polls, got %d", polls.Load())
	}
}

func TestCloudClient_WaitForDispatch_TerminalStatuses(t *testing.T) {
	t.Parallel()

	client := newTestCloudClient(t, "http://unused.invalid", "t")
	ctx := context.Background()

	complete := &DispatchDetail{ID: "r", Status: DispatchStatusComplete, GeneratedMarkdown: "x"}
	got, err := client.WaitForDispatch(ctx, complete, "")
	if err != nil || got != complete {
		t.Fatalf("complete run should return immediately, got %v %v", got, err)
	}

	reason := "model timed out"
	_, err = client.WaitForDispatch(ctx, &DispatchDetail{ID: "r", Status: DispatchStatusFailed, ErrorMessage: &reason}, "")
	if err == nil || !strings.Contains(err.Error(), "dispatch generation failed: model timed out") {
		t.Fatalf("expected failed-run error with reason, got %v", err)
	}

	_, err = client.WaitForDispatch(ctx, &DispatchDetail{ID: "r", Status: DispatchStatusFailed}, "")
	if err == nil || err.Error() != "dispatch generation failed" {
		t.Fatalf("expected bare failed-run error, got %v", err)
	}

	_, err = client.WaitForDispatch(ctx, &DispatchDetail{ID: "r", Status: "weird"}, "")
	if err == nil || !strings.Contains(err.Error(), `unexpected dispatch status "weird"`) {
		t.Fatalf("expected unexpected-status error, got %v", err)
	}

	_, err = client.WaitForDispatch(ctx, &DispatchDetail{Status: DispatchStatusGenerating}, "")
	if err == nil || !strings.Contains(err.Error(), "no id to poll") {
		t.Fatalf("expected missing-id error, got %v", err)
	}

	if _, err := client.WaitForDispatch(ctx, nil, ""); err == nil {
		t.Fatal("expected error for nil detail")
	}
}

