12	
13	// These tests swap package-level seams (newCellCoreClient /
14	// lookupDispatchRepoJurisdictions) and therefore must not run in parallel.
15	
16	func stubDispatchRepoJurisdictions(t *testing.T, fn func(context.Context, []string) map[string][]string) {
17		t.Helper()
18		prev := lookupDispatchRepoJurisdictions
19		lookupDispatchRepoJurisdictions = fn
20		t.Cleanup(func() { lookupDispatchRepoJurisdictions = prev })
21	}
22	
23	func TestDescribeDispatchRepoNotFound_AppendsPlacementHint(t *testing.T) {
24		stubDispatchRepoJurisdictions(t, func(_ context.Context, repos []string) map[string][]string {
25			if len(repos) != 2 {
26				t.Errorf("expected both missing repos to be looked up, got %v", repos)
27			}
28			return map[string][]string{
29				"entirehq/ferrata": {"us"},
30				"entirehq/plans":   {},
31			}
32		})
33	
34		err := describeDispatchRepoNotFound(context.Background(), &dispatchpkg.RepoNotFoundError{
35			Jurisdiction: "au",
36			Repos:        []string{"entirehq/ferrata", "entirehq/plans"},
37			Message:      "repository not found: entirehq/ferrata, entirehq/plans",
38		})
39		if err == nil {
40			t.Fatal("expected error")
41		}
42		msg := err.Error()
43		if !strings.HasPrefix(msg, "In AU: repository not found: entirehq/ferrata, entirehq/plans.") {
44			t.Fatalf("expected the dispatch error to lead, got %q", msg)
45		}
46		if !strings.Contains(msg, "\n  entirehq/ferrata is placed in: us") {
47			t.Fatalf("expected placement hint, got %q", msg)
48		}
49		if !strings.Contains(msg, "\n  entirehq/plans has no ready placement in any jurisdiction") {
50			t.Fatalf("expected no-placement hint, got %q", msg)
51		}
52	}
53	
54	func TestDescribeDispatchRepoNotFound_LeavesErrorAloneWithoutHint(t *testing.T) {
55		stubDispatchRepoJurisdictions(t, func(context.Context, []string) map[string][]string { return nil })
56	
57		original := &dispatchpkg.RepoNotFoundError{Jurisdiction: "us", Repos: []string{"a/b"}, Message: "repository not found: a/b"}
58		err := describeDispatchRepoNotFound(context.Background(), original)
59		var notFound *dispatchpkg.RepoNotFoundError
60		if !errors.As(err, &notFound) || notFound != original {
61			t.Fatalf("expected the original typed error when no hint is available, got %v", err)
62		}
63	
64		other := errors.New("boom")
65		if got := describeDispatchRepoNotFound(context.Background(), other); !errors.Is(got, other) {
66			t.Fatalf("non-404 errors must pass through untouched, got %v", got)
67		}
68	}
69	
70	func TestDefaultLookupDispatchRepoJurisdictions_UsesControlPlanePlacements(t *testing.T) {
71		fake := &fakeCellCore{repos: &coreapi.ListReposOutputBody{Repos: []coreapi.RepoIndexEntry{{
72			FullName: "entirehq/ferrata",
73			Placements: []coreapi.RepoPlacement{
74				{ID: "p1", Jurisdiction: "US", Status: coreapi.RepoPlacementStatusReady},
75				{ID: "p2", Jurisdiction: "us", Status: coreapi.RepoPlacementStatusProcessing},
76				{ID: "p3", Jurisdiction: "eu", Status: coreapi.RepoPlacementStatusFailed},
77				{ID: "p4", Jurisdiction: "au", Status: coreapi.RepoPlacementStatusReady},
78			},
79		}}}}
80		withFakeCellCore(t, fake)
81	
82		got := defaultLookupDispatchRepoJurisdictions(context.Background(), []string{"entirehq/ferrata"})
83		jurisdictions, ok := got["entirehq/ferrata"]
84		if !ok {
85			t.Fatalf("expected a placement entry, got %v", got)
86		}
87		if strings.Join(jurisdictions, ",") != "au,us" {
88			t.Fatalf("expected deduped, sorted, non-failed jurisdictions, got %v", jurisdictions)
89		}
90		if filter, ok := fake.lastListReposParams.Filter.Get(); !ok || filter != "entirehq/ferrata" {
91			t.Fatalf("expected an exact filtered index lookup, got %+v", fake.lastListReposParams)
92		}
93	}
94	
95	func TestDefaultLookupDispatchRepoJurisdictions_UnknownRepoIsAbsent(t *testing.T) {
96		withFakeCellCore(t, &fakeCellCore{repos: &coreapi.ListReposOutputBody{Repos: []coreapi.RepoIndexEntry{{
97			FullName:   "someone/else",
98			Placements: []coreapi.RepoPlacement{{ID: "p1", Jurisdiction: "us", Status: coreapi.RepoPlacementStatusReady}},
99		}}}})
100	
101		got := defaultLookupDispatchRepoJurisdictions(context.Background(), []string{"entirehq/ferrata"})
102		if _, ok := got["entirehq/ferrata"]; ok {
103			t.Fatalf("a repo the index does not name must not get a hint, got %v", got)
104		}
105	}
106	
107	func TestDefaultLookupDispatchRepoJurisdictions_ControlPlaneErrorIsSilent(t *testing.T) {
108		withFakeCellCore(t, &fakeCellCore{reposErr: errors.New("core down")})
109	
110		if got := defaultLookupDispatchRepoJurisdictions(context.Background(), []string{"entirehq/ferrata"}); len(got) != 0 {
111			t.Fatalf("expected no hint on control-plane error, got %v", got)
112		}
113	
114		prev := newCellCoreClient
115		newCellCoreClient = func() (cellCoreClient, error) { return nil, errors.New("no client") }
116		t.Cleanup(func() { newCellCoreClient = prev })
117		if got := defaultLookupDispatchRepoJurisdictions(context.Background(), []string{"entirehq/ferrata"}); got != nil {
118			t.Fatalf("expected nil when the control plane client cannot be built, got %v", got)
119		}
120	}

