20	func newTestCloudClient(t *testing.T, baseURL, token string) *CloudClient {
21		t.Helper()
22		transport := &http.Transport{DisableKeepAlives: true}
23		t.Cleanup(transport.CloseIdleConnections)
24		return NewCloudClient(CloudConfig{
25			BaseURL: baseURL,
26			Token:   token,
27			HTTP: &http.Client{
28				Transport: transport,
29				Timeout:   defaultCloudHTTPTimeout,
30			},
31		})
32	}
