34	// completeDispatchJSON is a terminal cell response in DispatchDetailWire shape.
35	func completeDispatchJSON(id, markdown string) string {
36		return fmt.Sprintf(`{"id":%q,"setupId":"setup-1","status":"complete","title":null,"coveredRepos":["entireio/cli"],"coveredRepoUlids":["01X"],"branches":[],"voice":null,"window":{"normalizedSince":"2026-04-09T00:00:00Z","normalizedUntil":"2026-04-16T00:00:00Z","firstCheckpointCreatedAt":null,"lastCheckpointCreatedAt":null},"totals":{"checkpoints":1,"usedCheckpointCount":1,"branches":1,"filesTouched":2},"repos":[],"generatedMarkdown":%q,"isPersisted":true,"errorMessage":null,"createdAt":"2026-04-16T00:00:00Z","updatedAt":"2026-04-16T00:00:01Z","completedAt":"2026-04-16T00:00:01Z"}`, id, markdown)
37	}
38	
39	func generatingDispatchJSON(id string) string {
40		return fmt.Sprintf(`{"id":%q,"setupId":"setup-1","status":"generating","title":null,"coveredRepos":["entireio/cli"],"branches":[],"voice":null,"window":{"normalizedSince":"2026-04-09T00:00:00Z","normalizedUntil":"2026-04-16T00:00:00Z","firstCheckpointCreatedAt":null,"lastCheckpointCreatedAt":null},"totals":{"checkpoints":1,"usedCheckpointCount":1,"branches":1,"filesTouched":2},"repos":[],"generatedMarkdown":"","isPersisted":true,"errorMessage":null,"createdAt":"2026-04-16T00:00:00Z","updatedAt":"2026-04-16T00:00:00Z","completedAt":null}`, id)
41	}
