43	// shortenDispatchPoll shrinks the package-level poll knobs for the duration of
44	// a test. Tests using it mutate shared state and must NOT call t.Parallel().
45	func shortenDispatchPoll(t *testing.T, interval, timeout time.Duration) {
46		t.Helper()
47		oldInterval, oldTimeout := dispatchPollInterval, dispatchPollTimeout
48		dispatchPollInterval, dispatchPollTimeout = interval, timeout
49		t.Cleanup(func() { dispatchPollInterval, dispatchPollTimeout = oldInterval, oldTimeout })
50	}
