119			}
120			w.Header().Set("Content-Type", "application/json")
121			w.WriteHeader(http.StatusOK)
122			_, _ = w.Write([]byte(completeDispatchJSON("run-1", "hi"))) //nolint:errcheck // test fixture response
123		}))
124		defer srv.Close()
125	
126		client := newTestCloudClient(t, srv.URL, "t")
