input.command:
cd /Users/alisha/Projects/cli && python3 - <<'EOF'
import os, pty, select, time, re, signal, fcntl, termios, struct
B=os.path.expanduser('~/.claude/tmp/cli-dispatch-jurisdiction/entire-dev')
pid, fd = pty.fork()
if pid == 0:
    os.environ['TERM']='xterm-256color'
    os.execv(B, [B, 'dispatch'])
fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 50, 120, 0, 0))
def clean(b):
    s=b.decode('utf-8','replace'); s=re.sub(r'\x1b\[[0-9;?>]*[A-Za-z]','',s); s=re.sub(r'\x1b[()=>][0-9A-Za-z]?','',s); return s.replace('\r','')
def read_until(pattern, timeout):
    buf=b''; end=time.time()+timeout
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.2)
        if r:
            try: buf+=os.read(fd,65536)
            except OSError: break
        if re.search(pattern, clean(buf)):
            time.sleep(0.8)
            r,_,_=select.select([fd],[],[],0.2)
            if r:
                try: buf+=os.read(fd,65536)
                except OSError: pass
            break
    return clean(buf)
repos=lambda s: re.findall(r'\[[ x•]\] (\S+)', s)
read_until(r'Cloud', 5); os.write(fd, b'\x1b[B'); time.sleep(0.3); os.write(fd, b'\r')
read_until(r'\(home\)', 30); os.write(fd, b'\x1b[B'); time.sleep(0.5); os.write(fd, b'\r')
s=read_until(r'\[ \] ', 15); print("AU repos:", len(repos(s)))
for name, seq in [("legacy shift+tab", b'\x1b[Z'), ("kitty shift+tab", b'\x1b[9;2u')]:
    os.write(fd, seq); s=read_until(r'Jurisdiction|offered next', 4)
    print(f"after {name}: on Jurisdiction group = {'offered next' in s}")
    if 'offered next' in s: break
print("screen tail:", re.sub(r'\n{2,}','\n', s)[-500:])
os.write(fd, b'\x1b[A'); time.sleep(0.5); os.write(fd, b'\r')
s=read_until(r'\[ \] ', 15); us=repos(s); print("US repos:", us[:10], "count:", len(us))
os.write(fd, b'\x03'); time.sleep(0.5)
try: os.kill(pid, signal.SIGKILL)
except Exception: pass
EOF

