/**
 * Build the DispatchFanoutDeps that reads each repo's checkpoints from the
 * caller's home cell. Default branches come from the home /repos listing the
 * caller already fetched during resolution, so no extra per-repo lookup is made.
 */
export function createHomeEntireApiCheckpointReader(
  config: DispatchHomeReaderConfig,
): DispatchFanoutDeps {
  return {
    fetchCheckpoints: async ({ repo, branch, limit }) => {
      const search = `?${new URLSearchParams({ branch, limit: String(limit) }).toString()}`
      const body = await readHomeJson<{ checkpoints?: EntireApiCheckpointInfo[] }>(
        config,
        `checkpoints read for ${repo.fullName}@${branch}`,
        `repos/${repo.repoUlid}/checkpoints`,
        search,
      )
      return body.checkpoints ?? []
    },
    resolveDefaultBranch: async (repo) => config.defaultBranchByUlid.get(repo.repoUlid) ?? "main",
  }
}

export interface HomeRepoListItem {
  id: string
  full_name: string
  default_branch?: string | null
}

/**
 * List the caller's repos from their home cell (in-region only). Used by the
 * bearer path to resolve selected slugs to their repo ULID + default branch.
 */
export async function listHomeRepos(
  config: Omit<DispatchHomeReaderConfig, "defaultBranchByUlid">,
): Promise<HomeRepoListItem[]> {
  const body = await readHomeJson<{ repos?: HomeRepoListItem[] }>(
    { ...config, defaultBranchByUlid: new Map() },
    "home repos listing",
    "repos",
    undefined,
  )
  return body.repos ?? []
}
