	huma.Register(api, publicCheckpointOp("repoCheckpoints", http.MethodGet, "/repos/{repo_id}/checkpoints",
		"Checkpoints on a branch, with commit, diffstat, and sessions", "checkpoints"),
		func(ctx context.Context, in *CheckpointsListInput) (*RepoCheckpointsOutput, error) {
			if deps.RepoAPIBase == "" {
				return nil, huma.Error500InternalServerError("repo api not configured", errors.New("RepoAPIBase empty"))
			}
			meta, _, err := deps.Store.GetRepoMeta(ctx, in.RepoID)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: repo meta", err)
			}
			// Branch membership: the branch's reachable commit set (read-through from
			// entiredb), intersected with the local checkpoint links.
			shas, err := deps.branchReachableForRequest(ctx, in.RepoID, in.Branch, meta)
			if err != nil {
				return nil, err
			}
			// Payload + resolved names + checkpoint count live under the storage repo
			// (identity when self-hosted); the links + repo identity stay on the code
			// repo. Resolve once for every payload-side read below.
			storageRepoID, err := deps.checkpointStorageRepoID(ctx, in.RepoID)
			if err != nil {
				return nil, err
			}
			since, until := parseSinceUntil(in.Since, in.Until)
			var sincePtr, untilPtr *time.Time
			if !since.IsZero() {
				sincePtr = &since
			}
			if !until.IsZero() {
				untilPtr = &until
			}
			rows, err := deps.Store.ListCheckpointsForCommits(ctx, in.RepoID, storageRepoID, shas, sincePtr, untilPtr, clampLimit(in.Limit, checkpointsDefault, checkpointsMaxLimit))
			if err != nil {
				return nil, huma.Error500InternalServerError("store: checkpoints", err)
			}
			out := &RepoCheckpointsOutput{}
			out.Body.Checkpoints, err = composeCheckpointsWithNames(ctx, deps, in.RepoID, storageRepoID, repoFullNameOr(meta, in.RepoID), rows)
