('''func defaultResolveDispatchWizardHome(ctx context.Context) string {
	home, err := auth.HomeJurisdictionFromActiveLogin(ctx, false)
	if err != nil {
		logging.Debug(ctx, "dispatch wizard: home jurisdiction unavailable", "error", err)
		return ""
	}
	return home
}''','''// defaultResolveDispatchWizardHome reads home_jurisdiction from the same
// account access token the dispatch itself will send, so the picker's default
// and the request's routing agree on which login they mean.
func defaultResolveDispatchWizardHome(ctx context.Context) string {
	token, err := auth.ResolveAccountAccessToken(ctx)
	if err == nil {
		var home string
		if home, err = auth.HomeJurisdictionFromLoginJWT(token); err == nil {
			home, err = auth.NormalizeJurisdiction(home)
		}
		if err == nil {
			return home
		}
	}
	logging.Debug(ctx, "dispatch wizard: home jurisdiction unavailable", "error", err)
	return ""
}'''),
])

# auth test: shared fixture for the stored-login setup, used by the new test
s=open('cmd/entire/cli/auth/cell_data_api_test.go').read()
start=s.index('func TestResolveAccountAccessToken_ReturnsRefreshedLoginJWTWithoutExchange(')
s=s[:start]+'''// seedStoredLoginContext isolates config/token storage, seeds one active login
// context whose core is a server that fails the test on ANY request (so a path
// that must not exchange or list can be asserted by silence), and returns the
// seeded login JWT.
func seedStoredLoginContext(t *testing.T) string {
	t.Helper()
	t.Setenv("ENTIRE_CONFIG_DIR", t.TempDir())
	t.Setenv("ENTIRE_API_BASE_URL", "https://entire.io")
	t.Setenv("ENTIRE_API_AUDIENCE_TEMPLATE", "")
	t.Setenv("ENTIRE_CORE_BASE_URL_TEMPLATE", "")
	t.Cleanup(tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json")))

	coreSrv := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		t.Errorf("unexpected core request %s %s", r.Method, r.URL.Path)
	}))
	t.Cleanup(coreSrv.Close)

	svc := tokenstore.CoreKeyringService(coreSrv.URL)
	loginJWT := makeJWT(t, fmt.Sprintf(`{"iss":%q,"home_jurisdiction":"us","exp":%d}`, coreSrv.URL, time.Now().Add(2*time.Hour).Unix()))
	if err := tokenstore.Set(svc, "me", tokenstore.EncodeTokenWithExpiration(loginJWT, 7200)); err != nil {
		t.Fatalf("seed token: %v", err)
	}
	ctxObj := &contexts.Context{Name: "me@core", CoreURL: coreSrv.URL, Handle: "me", KeychainService: svc}
	t.Cleanup(SetResolveContextForCellAPIForTest(t, func(context.Context, string, string, string, *http.Client, clusterdiscovery.DebugFunc) (*contexts.Context, error) {
		return ctxObj, nil
	}))
	return loginJWT
}

func TestResolveAccountAccessToken_ReturnsLoginJWTWithoutExchange(t *testing.T) {
	loginJWT := seedStoredLoginContext(t)

	got, err := ResolveAccountAccessToken(context.Background())
	if err != nil {
		t.Fatalf("ResolveAccountAccessToken: %v", err)
	}
	if got != loginJWT {
		t.Fatal("expected the stored login JWT to be returned verbatim")
	}
}
'''
open('cmd/entire/cli/auth/cell_data_api_test.go','w').write(s)
print("ok")
