16		"github.com/entireio/cli/cmd/entire/cli/api"
17		"github.com/entireio/cli/cmd/entire/cli/logging"
18		"github.com/entireio/cli/cmd/entire/cli/versioninfo"
19	)
20	
21	type CloudConfig struct {
22		BaseURL string
23		Token   string
24		HTTP    *http.Client
25		Timeout time.Duration
26	}
27	
28	type CloudClient struct {
29		baseURL string
30		token   string
31		http    *http.Client
32	}
33	
34	const defaultCloudHTTPTimeout = 120 * time.Second
35	
36	// The gateway's one-shot dispatch route (generated in-request, nothing
37	// persisted). `?jurisdiction=` is the gateway-only selector for which
38	// jurisdiction's cell generates it — see Options.Jurisdiction.
39	const (
40		dispatchGeneratePath   = "/api/v1/dispatches/generate"
41		jurisdictionQueryParam = "jurisdiction"
42	)
43	
44	func NewCloudClient(cfg CloudConfig) *CloudClient {
45		baseURL := cfg.BaseURL
46		if baseURL == "" {
47			baseURL = api.BaseURL()
48		}
49	
50		httpClient := cfg.HTTP
51		if httpClient == nil {
52			timeout := cfg.Timeout
53			if timeout <= 0 {
54				timeout = defaultCloudHTTPTimeout
55			}
56			httpClient = &http.Client{Timeout: timeout}
57		} else if cfg.Timeout > 0 && httpClient.Timeout == 0 {
58			httpClient.Timeout = cfg.Timeout
59		}
60	
61		return &CloudClient{
62			baseURL: strings.TrimRight(baseURL, "/"),
63			token:   cfg.Token,
64			http:    httpClient,
65		}
66	}
67	
68	type CreateDispatchRequest struct {
69		Repos    []string `json:"repos,omitempty"`
70		Since    string   `json:"since"`
71		Until    string   `json:"until"`
72		Generate bool     `json:"generate"`
73		Voice    string   `json:"voice,omitempty"`
74	}
75	
76	type CreateDispatchResponse struct {
77		// Jurisdiction is the slug the gateway stamps onto the response: the
78		// jurisdiction whose cell the dispatch was generated from. Empty from a
79		// gateway that predates the selector — see runServer for how a sent
80		// selector is checked against it.
81		Jurisdiction      string      `json:"jurisdiction,omitempty"`
82		Window            APIWindow   `json:"window"`
83		Title             string      `json:"title,omitempty"`
84		CoveredRepos      []string    `json:"covered_repos,omitempty"`
85		Branches          APIBranches `json:"branches,omitempty"`
86		Voice             *string     `json:"voice"`
87		Repos             []APIRepo   `json:"repos,omitempty"`
88		Totals            APITotals   `json:"totals"`
89		Warnings          APIWarnings `json:"warnings"`
90		GeneratedText     string      `json:"generated_text,omitempty"`
91		GeneratedMarkdown string      `json:"generated_markdown,omitempty"`
92	}
93	
94	type APIBranches struct {
95		Values []string
96		All    bool
97	}
98	
99	type APIWindow struct {
100		NormalizedSince          string `json:"normalized_since"`
101		NormalizedUntil          string `json:"normalized_until"`
102		FirstCheckpointCreatedAt string `json:"first_checkpoint_created_at,omitempty"`
103		LastCheckpointCreatedAt  string `json:"last_checkpoint_created_at,omitempty"`
104	}
105	
106	type APIRepo struct {
107		FullName string       `json:"full_name"`
108		URL      string       `json:"url,omitempty"`
109		Sections []APISection `json:"sections"`
110	}
111	
112	type APISection struct {
113		Label   string      `json:"label"`
114		Bullets []APIBullet `json:"bullets"`
115	}
116	
117	type APIBullet struct {
118		CheckpointID string   `json:"checkpoint_id"`
119		Text         string   `json:"text"`
120		Source       string   `json:"source"`
121		Branch       string   `json:"branch"`
122		CreatedAt    string   `json:"created_at"`
123		Labels       []string `json:"labels"`
124	}
125	
126	type APITotals struct {
127		Checkpoints         int `json:"checkpoints"`
128		UsedCheckpointCount int `json:"used_checkpoint_count"`
129		Branches            int `json:"branches"`
130		FilesTouched        int `json:"files_touched"`
131	}
132	
133	type APIWarnings struct {
134		AccessDeniedCount  int `json:"access_denied_count"`
135		PendingCount       int `json:"pending_count"`
136		FailedCount        int `json:"failed_count"`
137		UnknownCount       int `json:"unknown_count"`
138		UncategorizedCount int `json:"uncategorized_count"`
139		TruncatedCount     int `json:"truncated_count"`
140	}
141	
142	func (b *APIBranches) UnmarshalJSON(data []byte) error {
143		if bytes.Equal(data, []byte("null")) {
144			*b = APIBranches{}
145			return nil
146		}
147	
148		var values []string
149		if err := json.Unmarshal(data, &values); err == nil {
150			*b = APIBranches{Values: values}
151			return nil
152		}
153	
154		var sentinel string
155		if err := json.Unmarshal(data, &sentinel); err != nil {
156			return fmt.Errorf("decode branches: %w", err)
157		}
158		if sentinel != "all" {
159			return fmt.Errorf("decode branches: unexpected sentinel %q", sentinel)
160		}
161		*b = APIBranches{All: true}
162		return nil
163	}
164	
165	// RepoNotFoundError is the gateway's 404 for a repo that is not placed in (or
166	// not visible in) the jurisdiction the request was routed to — a repo mirrored
167	// only in US, requested from an AU home, is simply unknown to the AU cell.
168	// Jurisdiction is the selector the caller sent ("" = home) and Home the
169	// caller's home jurisdiction when known (so callers know which cell answered
170	// when no selector was sent); Repos are the requested slugs the gateway's
171	// message named; Message is its sentence; Cause is the underlying
172	// *api.HTTPError.
173	type RepoNotFoundError struct {
174		Jurisdiction string
175		Home         string
176		Repos        []string
177		Message      string
178		Cause        error
179	}
180	
181	// FailedJurisdiction is the jurisdiction whose cell answered "not found": the
182	// selector when one was sent, else the home jurisdiction ("" if unknown).
183	func (e *RepoNotFoundError) FailedJurisdiction() string {
184		if j := strings.TrimSpace(e.Jurisdiction); j != "" {
185			return j
186		}
187		return e.Home
188	}
189	
190	const repoNotFoundPrefix = "repository not found"
191	
192	func (e *RepoNotFoundError) Error() string {
193		scope := "your home jurisdiction"
194		if j := strings.TrimSpace(e.Jurisdiction); j != "" {
195			scope = strings.ToUpper(j)
196		}
197		// Render our own sentence when the repos were parsed, so the wording does
198		// not depend on (or double up with) the gateway's prose; fall back to its
199		// message only when parsing found nothing.
200		sentence := e.Message
201		if len(e.Repos) > 0 {
202			sentence = repoNotFoundPrefix + ": " + strings.Join(e.Repos, ", ")
203		}
204		return "In " + scope + ": " + sentence + ". Pick a jurisdiction the repository is mirrored into (entire dispatch --jurisdiction <slug>), or mirror it there."
205	}
206	
207	func (e *RepoNotFoundError) Unwrap() error { return e.Cause }
208	
209	// statusError keeps the dispatch command's established non-2xx wording while
210	// exposing the shared *api.HTTPError underneath (errors.As /
211	// api.IsHTTPErrorStatus), so dispatch failures classify like any other API call.
212	type statusError struct {
213		*api.HTTPError
214	}
215	
216	func (e *statusError) Error() string {
217		if e.Message == "" {
218			return fmt.Sprintf("dispatch service returned status %d", e.StatusCode)
219		}
220		return fmt.Sprintf("dispatch service returned status %d: %s", e.StatusCode, strconv.Quote(e.Message))
221	}
222	
223	func (e *statusError) Unwrap() error { return e.HTTPError }
224	
225	// CreateDispatch generates a one-off dispatch from the cell of `jurisdiction`
226	// ("" = the caller's home jurisdiction).
227	func (c *CloudClient) CreateDispatch(ctx context.Context, reqBody CreateDispatchRequest, jurisdiction string) (*CreateDispatchResponse, error) {
228		path := dispatchGeneratePath
229		if j := strings.TrimSpace(jurisdiction); j != "" {
230			path += "?" + jurisdictionQueryParam + "=" + url.QueryEscape(j)
231		}
232	
233		var out CreateDispatchResponse
