cd /Users/alisha/.marvin/worktrees/cli/cli-dispatch-jurisdiction; python3 - <<'PYEOF'
def sub(p, pairs):
    s=open(p).read()
    for a,b in pairs:
        if a not in s: raise SystemExit(f"NO MATCH in {p}: {a[:80]!r}")
        s=s.replace(a,b,1)
    open(p,'w').write(s)
sub('cmd/entire/cli/dispatch_wizard_scope.go', [
('''// reposIn lists the offerable repos in a jurisdiction. "" is the unscoped
// bucket: repos without a placement when home is unknown (every repo, when
// nothing is placed at all).
func (s *dispatchWizardScope) reposIn(jurisdiction string) []string {
	return s.byJurisdiction[jurisdiction]
}''','''// reposIn lists the offerable repos in a jurisdiction. "" (or the select's
// dispatchWizardJurisdictionHome sentinel) is the unscoped bucket: repos
// without a placement when home is unknown (every repo, when nothing is placed
// at all).
func (s *dispatchWizardScope) reposIn(jurisdiction string) []string {
	if jurisdiction == dispatchWizardJurisdictionHome {
		jurisdiction = ""
	}
	return s.byJurisdiction[jurisdiction]
}'''),
('''// options renders the jurisdiction select, default first — huh seeds the bound
// value from the first option, so the ordering IS the default. The unscoped
// "Home" ("" — selector unsent) choice appears when it holds repos, and alone
// when nothing is placed anywhere.''','''// options renders the jurisdiction select, default first — huh seeds the bound
// value from the first option, so the ordering IS the default. The unscoped
// "Home" choice (selector unsent) appears when it holds repos, and alone when
// nothing is placed anywhere. Its value is the dispatchWizardJurisdictionHome
// sentinel, never "": huh pre-selects the option equal to the field's current
// value, and the field starts at "", so a ""-valued option would steal the
// default whenever it is listed. resolve() maps the sentinel back to "".'''),
('''		options = append(options, huh.NewOption("Home", ""))''','''		options = append(options, huh.NewOption("Home", dispatchWizardJurisdictionHome))'''),
])
sub('cmd/entire/cli/dispatch_wizard.go', [
('''	// dispatchWizardJurisdictionHome labels the blank selector: the caller's
	// home jurisdiction, which is where the gateway routes when none is sent.
	dispatchWizardJurisdictionHome = "home"''','''	// dispatchWizardJurisdictionHome is the jurisdiction select's value for
	// "send no selector" (the gateway then routes to the caller's home) and
	// the summary label for it. A sentinel rather than "" because huh
	// pre-selects the option matching the field's initial "" value.
	dispatchWizardJurisdictionHome = "home"'''),
('''	jurisdiction := ""
	if !s.isLocal() {
		jurisdiction = s.jurisdiction
	}''','''	jurisdiction := ""
	if !s.isLocal() && s.jurisdiction != dispatchWizardJurisdictionHome {
		jurisdiction = s.jurisdiction
	}'''),
])
s=open('cmd/entire/cli/dispatch_wizard_scope_test.go').read()
a='''			labels := make([]string, 0)
			for _, option := range scope.options() {
				labels = append(labels, option.Key)
			}'''
b='''			labels := make([]string, 0)
			for _, option := range scope.options() {
				labels = append(labels, option.Key)
				if option.Value == "" {
					t.Fatalf("option %q has the empty value, which huh would pre-select over the default", option.Key)
				}
			}'''
if a not in s: raise SystemExit("no match test")
s=s.replace(a,b,1)
s=s.replace('''			reposIn:     map[string]string{"us": "acme/us-only,acme/both", "au": "acme/unplaced", "": ""},''','''			reposIn:     map[string]string{"us": "acme/us-only,acme/both", "au": "acme/unplaced", "": "", dispatchWizardJurisdictionHome: ""},''')
s=s.replace('''			reposIn:     map[string]string{"us": "a/placed", "": "a/unplaced"},''','''			reposIn:     map[string]string{"us": "a/placed", "": "a/unplaced", dispatchWizardJurisdictionHome: "a/unplaced"},''')
open('cmd/entire/cli/dispatch_wizard_scope_test.go','w').write(s)
s=open('cmd/entire/cli/dispatch_wizard_test.go').read()
a='''	state.jurisdiction = "not a slug"
	if _, err := state.resolve(); err == nil || !strings.Contains(err.Error(), "invalid --jurisdiction") {
		t.Fatalf("expected slug validation through resolve, got %v", err)
	}
}'''
b='''	state.jurisdiction = "not a slug"
	if _, err := state.resolve(); err == nil || !strings.Contains(err.Error(), "invalid --jurisdiction") {
		t.Fatalf("expected slug validation through resolve, got %v", err)
	}

	// The select's "Home" choice is a sentinel; it must resolve to "no selector".
	state.jurisdiction = dispatchWizardJurisdictionHome
	opts, err = state.resolve()
	if err != nil {
		t.Fatal(err)
	}
	if opts.Jurisdiction != "" {
		t.Fatalf("Home must resolve to an empty jurisdiction, got %q", opts.Jurisdiction)
	}
}'''
if a not in s: raise SystemExit("no match wizard test")
open('cmd/entire/cli/dispatch_wizard_test.go','w').write(s.replace(a,b,1))
